const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
const root=path.resolve(__dirname,'../students'),read=f=>fs.readFileSync(path.join(root,f),'utf8');let checks=0;const ok=(v,m)=>{assert.ok(v,m);checks++};
(async()=>{const dom=new JSDOM(read('index.html'),{url:'https://example.test/students/#symbols',runScripts:'outside-only'}),w=dom.window,d=w.document;await new Promise(resolve=>w.addEventListener('load',resolve,{once:true}));for(const m of read('index.html').matchAll(/src="([^"?]+\.js)/g))w.eval(read(m[1]));const S=w.MT_SYMBOLS;
const all=S.concepts.flatMap(c=>c.contexts);ok(all.length===S.entries.length&&new Set(all).size===S.entries.length,'Every underlying context appears in exactly one concept');ok(S.concepts.length<S.entries.length/2,'Repeated contexts consolidate substantially');
for(const c of S.concepts){ok(c.contexts.every(e=>w.MT_SYMBOL_REVIEW.canonical(e).unit===c.unit),'Units are not silently merged: '+c.id);ok(c.references.reduce((n,r)=>n+r.contexts.length,0)===c.contexts.length,'All formula references retained: '+c.id)}
ok(S.findConcepts('∇').length===1&&S.findConcepts('∇')[0].references.length===4,'Six displacement-volume contexts share one card and four formula links');ok(S.findConcepts('′').length===1&&S.findConcepts('′')[0].contexts.length===2,'Derivative synonyms consolidate');
for(const unit of ['C','m³/s','J'])ok(S.findConcepts('Q').some(c=>c.unit===unit),'Q retains distinct quantity unit '+unit);
ok(S.entries.some(e=>e.symbol==='PB'&&e.meaning==='Proportional band'),'PB retains actual proportional-band formula');ok(!S.entries.some(e=>e.symbol==='P'&&e.meaning==='Proportional band'),'Unreferenced P alias removed');
ok(S.entries.filter(e=>e.symbol==='BMEP').every(e=>e.meaning==='Brake mean effective pressure'),'BMEP is not labelled absolute gas pressure');
for(const s of ['c_p','c_v'])ok(S.entries.some(e=>e.symbol===s&&e.meaning.includes('Specific heat capacity')),'Individual heat capacity definition '+s);
for(const f of w.MT_FORMULAS)for(const v of f.related||[])if(v.symbolicStatus==='NOT_APPLICABLE')for(const c of S.entries.filter(e=>e.variantId===v.id))ok(!c.status.includes('Symbolic rule checked'),'Non-symbolic source status stays honest');
ok(d.querySelectorAll('.symbol-context').length===60,'Initial page is bounded to60 concept cards');d.getElementById('symbol-more').click();ok(d.querySelectorAll('.symbol-context').length===120,'Show more appends next60');
const search=d.getElementById('symbol-search');search.value='∇';search.dispatchEvent(new w.Event('input'));ok(d.querySelectorAll('.symbol-context').length===1,'Search resets paging and renders one displacement-volume card');ok(d.getElementById('symbol-more').hidden,'Show more hidden when exhausted');
const card=d.querySelector('.symbol-context');ok(card.textContent.includes('Used in 4 formulas'),'Formula family count visible without repeated cards');const variant=card.querySelector('[data-symbol-variant]');ok(variant,'Precise source variant link available');variant.closest('details').open=true;variant.click();const source=d.getElementById(variant.dataset.symbolVariant);ok(source&&source.closest('details').open,'Variant navigation opens its source expression');await new Promise(resolve=>w.setTimeout(resolve,0));ok(d.getElementById(variant.dataset.symbolVariant).closest('details').open,'Source variant remains open after the hash route event');
search.value='Q';d.getElementById('symbol-discipline').value='electrical';search.dispatchEvent(new w.Event('input'));ok([...d.querySelectorAll('.symbol-context')].every(e=>!e.textContent.includes('Volumetric flow rate')),'Discipline filter excludes unrelated flow context');
for(const p of fs.readdirSync(root).filter(f=>f.endsWith('.html'))){const page=new JSDOM(read(p)),nav=page.window.document.querySelector('header .student-nav');ok(nav?.querySelectorAll('a').length===4,'Shared navigation on '+p);ok(nav.querySelector('[aria-current="page"]'),'Current destination on '+p);page.window.close()}
ok(d.querySelectorAll('.hero-buttons a').length===2,'Landing page has two clear starting actions');let scrolled=false;d.getElementById('study-tools').scrollIntoView=()=>{scrolled=true};d.getElementById('library-home-link').click();ok(scrolled&&d.getElementById('formula-count').textContent==='575 / 575','Library navigation resets filters and targets the actual study tools rather than the hero');
const workspace=new JSDOM(read('interactive.html'),{url:'https://example.test/students/interactive.html#tank',runScripts:'outside-only'}),q=workspace.window,qd=q.document;q.eval(read('interactive.js'));ok(qd.querySelectorAll('#module-list a').length===15&&qd.querySelectorAll('#module-list h3').length===5,'All15 modules grouped by five subjects');qd.getElementById('module-search').value='pump';qd.getElementById('module-search').dispatchEvent(new q.Event('input'));ok([...qd.querySelectorAll('#module-list a')].filter(a=>!a.hidden).length===1,'Module search narrows navigation');
const frame=qd.querySelector('iframe');frame.contentDocument.open();frame.contentDocument.write('<!doctype html><html><head></head><body><header>Duplicate header</header><main><a id="chapter-link" href="./#chapter-14">Chapter</a><label>Experiment<select id="module"></select></label></main></body></html>');frame.contentDocument.close();frame.dispatchEvent(new q.Event('load'));ok(frame.contentDocument.getElementById('workspace-embed-style'),'Embedded view removes duplicate navigation');ok(frame.contentDocument.getElementById('module').closest('label').hidden,'Outer module choice stays authoritative');ok(frame.contentDocument.getElementById('chapter-link').target==='_top','Chapter links exit the embedded module into the main study workspace');
frame.contentDocument.open();frame.contentDocument.write('<!doctype html><html><head></head><body><main><form>Sign in</form></main></body></html>');frame.contentDocument.close();frame.dispatchEvent(new q.Event('load'));ok(!frame.contentDocument.getElementById('workspace-embed-style'),'Non-module authentication content is not decorated');ok(!frame.hasAttribute('scrolling'),'Authentication documents retain normal browser scrolling');
console.log(JSON.stringify({status:'PASS',checks,contexts:S.entries.length,distinctMeanings:S.concepts.length,reviewedCorrections:w.MT_SYMBOL_REVIEW.corrections.length,scope:'Semantic grouping, explicit label corrections, preserved formula contexts, pagination, filters, variant destinations and shared navigation'}));w.close();q.close();})().catch(e=>{console.error(e);process.exitCode=1});
